{
  "root_cause": "The Radios component only listens for click events on its module container, missing keyboard-driven change events when arrowing between radio groups in separate module containers. The click handler only processes radios within its own module, not the full radio group sharing the same name across modules.",
  "repair_strategy": "Add a change event listener on the form ancestor to capture cross-module keyboard navigation, and update the handler to query all radios sharing the same name globally, ensuring conditional visibility updates for the entire radio group.",
  "edits": [
    {
      "path": "src/govuk/components/radios/radios.js",
      "sha256": "a5f3970a55a7d3dd59bfdfb0ef82c8f9f8fd2ace3eefa606ec486fb263e86b8c",
      "before": "Radios.prototype.init = function () {
  var $module = this.$module
  var $inputs = this.$inputs

  /**
  * Loop over all items with [data-controls]
  * Check if they have a matching conditional reveal
  * If they do, assign attributes.
  **/
  nodeListForEach($inputs, function ($input) {
    var controls = $input.getAttribute('data-aria-controls')

    // Check if input controls anything
    // Check if content exists, before setting attributes.
    if (!controls || !$module.querySelector('#' + controls)) {
      return
    }

    // If we have content that is controlled, set attributes.
    $input.setAttribute('aria-controls', controls)
    $input.removeAttribute('data-aria-controls')
    this.setAttributes($input)
  }.bind(this))

  // Handle events
  $module.addEventListener('click', this.handleClick.bind(this))
}",
      "after": "Radios.prototype.init = function () {
  var $module = this.$module
  var $inputs = this.$inputs

  /**
  * Loop over all items with [data-controls]
  * Check if they have a matching conditional reveal
  * If they do, assign attributes.
  **/
  nodeListForEach($inputs, function ($input) {
    var controls = $input.getAttribute('data-aria-controls')

    // Check if input controls anything
    // Check if content exists, before setting attributes.
    if (!controls || !$module.querySelector('#' + controls)) {
      return
    }

    // If we have content that is controlled, set attributes.
    $input.setAttribute('aria-controls', controls)
    $input.removeAttribute('data-aria-controls')
    this.setAttributes($input)
  }.bind(this))

  // Handle events
  $module.addEventListener('click', this.handleChange.bind(this))
  var $form = $module.closest('form')
  if ($form) {
    $form.addEventListener('change', this.handleChange.bind(this))
  }
}"
    },
    {
      "path": "src/govuk/components/radios/radios.js",
      "sha256": "a5f3970a55a7d3dd59bfdfb0ef82c8f9f8fd2ace3eefa606ec486fb263e86b8c",
      "before": "Radios.prototype.handleClick = function (event) {
  nodeListForEach(this.$inputs, function ($input) {
    // If a radio with aria-controls, handle click
    var isRadio = $input.getAttribute('type') === 'radio'
    var hasAriaControls = $input.getAttribute('aria-controls')
    if (isRadio && hasAriaControls) {
      this.setAttributes($input)
    }
  }.bind(this))
}",
      "after": "Radios.prototype.handleChange = function (event) {
  var $target = event.target
  var radioName = $target.getAttribute('name')
  if (!radioName) return
  var allRadios = document.querySelectorAll('input[type="radio"][name="' + radioName + '"]')
  nodeListForEach(allRadios, function ($input) {
    var hasAriaControls = $input.getAttribute('aria-controls')
    if (hasAriaControls) {
      this.setAttributes($input)
    }
  }.bind(this))
}"
    }
  ],
  "expected_accessibility_effect": "Keyboard navigation (arrow keys) between radio options across module boundaries will correctly show/hide associated conditional fields, satisfying WCAG 2.1.1 (Keyboard), 2.4.3 (Focus Order), and 4.1.2 (Name, Role, Value).",
  "functional_risks": [
    "Duplicate processing when both click and change events fire for the same interaction (idempotent setAttributes mitigates this).",
    "Form ancestor not found in edge cases (falls back to module-only click handling).",
    "Multiple Radios instances on the same form each attach form change listeners (harmless duplication)."
  ],
  "verification_requirements": [
    "Verify arrow key navigation from Text message to opt-out hides mobile number field.",
    "Verify arrow key navigation from opt-out to Email shows email field.",
    "Verify mouse click selection continues to work.",
    "Verify form data reflects selected radio value.",
    "Verify ARIA attributes and conditional visibility update appropriately."
  ]
}
